import json, subprocess

def post_form(endpoint, params):
    args = ["curl","-s","-X","POST",f"https://slack.com/api/{endpoint}", "-d", "token=<TOKEN>"]
    for k,v in params.items():
        args += ["-d", f"{k}={v}"]
    out = subprocess.run(args, capture_output=True, text=True).stdout
    return json.loads(out)

for p in (
    {"channel":"C_INC","oldest":"1790049600","latest":"1790136000","limit":"999"},
    {"channel":"incidents","oldest":"1790049600","latest":"1790136000","limit":"999"},
):
    d = post_form("conversations.history", p)
    print(list(p), d.get("ok"), d.get("error"))
    if d.get("ok"):
        print(json.dumps(d)[:800])
        break
EOF

